def extract_json(text: str) -> dict:
    text = text.strip()
    text = re.sub(r"^```(?:json)?", "", text).strip()
    text = re.sub(r"```$", "", text).strip()
    start = text.find("{")
    end = text.rfind("}")
    if start == -1 or end == -1:
        raise ValueError("Javobda JSON topilmadi")
    return json.loads(text[start:end + 1])


REQUIRED_FIELDS = [
    "official_name", "capital", "language", "population", "area", "government",
    "description", "geography", "currency", "presidents_count", "presidents",
    "symbols", "events",
]


@app.get("/api/country/{name}")
def get_country_info(name: str):
    name = name.strip()
    if not name:
        raise HTTPException(400, "Davlat nomi bo'sh bo'lishi mumkin emas")

    with get_db() as conn:
        row = conn.execute(
            "SELECT data_json FROM country_info WHERE name = ?", (name,)
        ).fetchone()
        if row:
            data = json.loads(row["data_json"])
            data["name"] = name
            data["cached"] = True
            return data

    if not groq_client:
        raise HTTPException(500, "GROQ_API_KEY sozlanmagan")

    try:
        completion = groq_client.chat.completions.create(
            model=GROQ_MODEL,
            messages=[
                {"role": "system", "content": SYSTEM_PROMPT},
                {"role": "user", "content": f"Davlat: {name}"},
            ],
            temperature=0.5,
            max_tokens=1800,
        )
        raw = completion.choices[0].message.content
        parsed = extract_json(raw)
        for field in REQUIRED_FIELDS:
            parsed.setdefault(field, "" if field != "events" and field != "presidents" else [])
    except Exception as e:
        raise HTTPException(502, f"AI javobini olishda xatolik: {e}")

    with get_db() as conn:
        conn.execute(
            "INSERT OR REPLACE INTO country_info (name, data_json) VALUES (?, ?)",
            (name, json.dumps(parsed, ensure_ascii=False)),
        )

    parsed["name"] = name
    parsed["cached"] = False
    return parsed


# ---------------------------------------------------------------------------
# Frontend (single-file bundle): the whole globe UI (HTML/CSS/JS) is embedded
# below as base64, so the entire backend + frontend ships as ONE Python file.
# ---------------------------------------------------------------------------
_INDEX_HTML_B64 = ""
INDEX_HTML = base64.b64decode(_INDEX_HTML_B64).decode("utf-8")


@app.get("/", response_class=HTMLResponse)
def serve_index():
    return HTMLResponse(content=INDEX_HTML)
